  z<-mat[!rownames(mat)%in%if(mask=='M20')M20 else character(),,drop=FALSE];ss<-lapply(sets,function(g)setdiff(g,if(mask=='M20')M20 else character()));cv<-rbindlist(lapply(names(ss),function(s)data.table(family=fam,mask=mask,signature=s,n_expected=length(ss[[s]]),n_measured=sum(ss[[s]]%in%b$feature_universe),n_covered=sum(ss[[s]]%in%rownames(z)),covered_genes=paste(intersect(ss[[s]],rownames(z)),collapse=';'))));cv[,evaluable:=n_covered>=5&n_covered/n_expected>=.5];cov[[paste(fam,mask)]]<-cv
  ok<-cv[evaluable==TRUE,signature];if(length(ok)){res<-gsva(ssgseaParam(z,ss[ok],minSize=5,alpha=.25,normalize=FALSE),verbose=FALSE,BPPARAM=BiocParallel::SerialParam(progressbar=FALSE));a<-as.data.table(as.table(res));setnames(a,c('signature','profile_id','raw_score'));a[,`:=`(family=fam,mask=mask,variant='standard')];allsc[[paste(fam,mask)]]<-a}
  for(s in names(ss)){idx<-idx+1;g<-ss[[s]];gg[[idx]]<-data.table(family=fam,mask=mask,signature=s,gene=g,in_original_features=g%in%b$feature_universe,in_fixed_universe=g%in%rownames(z))}
 }
