k_old<-o$genes;k_oldgroup<-makekeep(main$profile_id);k_new<-mats[['Capillary EC']]$gene_universe;k_newdesign<-makekeep(ref$profile_id,model.matrix(~factor(dataset)+Q50_z,ref));oldactual<-makekeep(main$profile_id,o$design);stopifnot(setequal(oldactual,k_old))
cv<-data.table(gene=g,in_source=g%in%allfeat,old_design_keep=g%in%k_old,old_samples_group_keep=g%in%k_oldgroup,new_fixed_keep=g%in%k_new,new_samples_design_keep=g%in%k_newdesign,MP10=g%in%M20);ge<-fread(file.path(OLD,'tables/gsea/M0073_Hallmark_Full.tsv.gz'));print(names(ge));le<-strsplit(ge[pathway=='HALLMARK_MTORC1_SIGNALING',leadingEdge],';',fixed=TRUE)[[1]];cv[,old_leading_edge:=gene%in%le];cv[,exclusion_reason:=fifelse(!in_source,'feature_absent',fifelse(new_fixed_keep,'retained_fixed_background',fifelse(old_design_keep,'old_design_retains_new_group_filter_excludes','both_filters_exclude')))];put(cv,'mTORC1_EC_filter_audit.tsv')
cc<-b$counts[intersect(g,allfeat),cap$profile_id,drop=FALSE];det<-b$detected_cells[rownames(cc),colnames(cc),drop=FALSE];cp<-cpm(DGEList(cc,lib.size=b$profiles[match(cap$profile_id,profile_id),total_counts]));long<-as.data.table(as.table(as.matrix(cc)));setnames(long,c('gene','profile_id','raw_counts'));long[,detected_cells:=as.vector(as.matrix(det))];long[,CPM:=as.vector(cp)];long<-merge(long,cap[,.(profile_id,sample_uid,dataset,n_cells,Q50,Q95,main_patient)],by='profile_id');long[,detected_fraction:=detected_cells/n_cells];put(long,'mTORC1_EC_gene_detection_CPM.tsv.gz');put(main,'mTORC1_M0073_membership.tsv');put(data.table(profile_id=main$profile_id,o$design),'mTORC1_M0073_design.tsv');put(data.table(sample_uid=main$sample_uid,dataset=main$dataset,Q50=main$Q50,Q50_z=main$Q50_z,leverage=diag(o$design%*%solve(crossprod(o$design))%*%t(o$design)),residual_df=nrow(o$design)-qr(o$design)$rank),'mTORC1_M0073_leverage.tsv')
# Existing repaired epithelial Full/M20 and historical receiver evidence; original P/q labels retained.
ev<-list();for(id in c('M0001','M0016','M0031','M0073'))for(mask in c('Full','M20-masked')){p<-if(id=='M0031')file.path(V1,'tables/gsea_repair',paste0(id,'_Hallmark_',mask,'.tsv.gz'))else file.path(OLD,'tables/gsea',paste0(id,'_Hallmark_',mask,'.tsv.gz'));if(!file.exists(p))next;d<-fread(p)[pathway=='HALLMARK_MTORC1_SIGNALING'];d[,`:=`(source_model=id,mask=mask,source_path=p,expression_source=if(id=='M0073')'Capillary EC RNA'else'Epi RNA',exposure=if(id=='M0073')'Epi MP10 Q50 continuous'else paste0(c(M0001='H50',M0016='H10',M0031='H05')[id],' vs L50'))];ev[[paste(id,mask)]]<-d};ev<-rbindlist(ev,fill=TRUE);put(ev,'mTORC1_singlecell_source_evidence.tsv')
